import java.util.*;

public class KthLargest {
    int k;
    List<Integer> nums;

    KthLargest(int k, int[] initial) {
        this.k = k;
        nums = new ArrayList<>();
        for (int x : initial) nums.add(x);
    }

    int add(int val) {
        nums.add(val);
        Collections.sort(nums);            // re-sort everything seen so far
        return nums.get(nums.size() - k);
    }
}

