import java.util.*;

public class KthLargest {
    int k;
    PriorityQueue<Integer> heap = new PriorityQueue<>();

    KthLargest(int k, int[] initial) {
        this.k = k;
        for (int x : initial) add(x);
    }

    int add(int val) {
        heap.offer(val);
        if (heap.size() > k) heap.poll();   // discard the value no longer in the top k
        return heap.peek();
    }
}

